function testBubbleSort() {
    const testCases = [
        { input: [], expected: [] },
        { input: [5], expected: [5] },
        { input: [1, 2, 3, 4], expected: [1, 2, 3, 4] },
        { input: [4, 3, 2, 1], expected: [1, 2, 3, 4] },
        { input: [3, 2, 1, 2, 3], expected: [1, 2, 2, 3, 3] },
        { input: [2, 2, 2], expected: [2, 2, 2] },
        { input: [5, 1, 4, 2, 8], expected: [1, 2, 4, 5, 8] },
        { input: [10, 9, 8, 7, 6, 5], expected: [5, 6, 7, 8, 9, 10] },
    ];

    testCases.forEach((testCase, index) => {
        const result = bubbleSort(testCase.input);
        const passed = JSON.stringify(result) === JSON.stringify(testCase.expected);
        console.log(`Test case ${index + 1}: ${passed ? 'Passed' : 'Failed'}`);
    });
}

// Run the tests
testBubbleSort();
```

