import random

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_palindrome(n):
    return str(n) == str(n)[::-1]

primes = []
while len(primes) < 10:
    num = random.randint(500, 1000)
    if is_prime(num) and is_palindrome(num):
        primes.append(num)

primes_tuple = tuple(primes)
print(primes_tuple)
```

