```python
# views.py
import json
from datetime import datetime
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from AppCoder.models import Curso, Entregable

@csrf_exempt
def curso(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            nombre = data.get('nombre')
            camada = data.get('camada')

            if not nombre or not camada:
                return JsonResponse({'error': 'Missing required fields: nombre and camada'}, status=400)

            try:
                camada = int(camada)
            except (ValueError, TypeError):
                return JsonResponse({'error': 'Camada must be an integer'}, status=400)

            curso = Curso(nombre=nombre, camada=camada)
            curso.save()

            return JsonResponse({
                'curso': curso.nombre,
                'camada': curso.camada
            }, status=201)

        except json.JSONDecodeError:
            return JsonResponse({'error': 'Invalid JSON format'}, status=400)
        except Exception as e:
            return JsonResponse({'error': str(e)}, status=500)

    return JsonResponse({'error': 'Method not allowed'}, status=405)


@csrf_exempt
def entregables(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            nombre = data.get('nombre')
            fechaEntrega = data.get('fechaEntrega')

            if not nombre or not fechaEntrega:
                return JsonResponse({'error': 'Missing required fields: nombre and fechaEntrega'}, status=400)

            try:
                fechaEntrega = datetime.strptime(fechaEntrega, '%Y-%m-%d').date()
            except (ValueError, TypeError):
                return JsonResponse({'error': 'FechaEntrega must be in YYYY-MM-DD format'}, status=400)

            entregable = Entregable(nombre=nombre, fechaEntrega=fechaEntrega)
            entregable.save()

            return JsonResponse({
                'entregable': entregable.nombre,
                'fechaEntrega': entregable.fechaEntrega
            }, status=201)

        except json.JSONDecodeError:
            return JsonResponse({'error': 'Invalid JSON format'}, status=400)
        except Exception as e:
            return JsonResponse({'error': str(e)}, status=500)

    return JsonResponse({'error': 'Method not allowed'}, status=405)
