            'created_at': '2023-04-01T13:00:00',
            'user_id': 'user_2'
        }
    }
    tweets_instance = Tweets.from_dict(input_dict)
    assert tweets_instance.to_dict() == input_dict

    # Test case 2: Error handling
    try:
        invalid_input_dict = {
            '789': {
